/*
 * CONCEPT 10 - CHRISTMAS MOBILE GIFT SHOPPING
 * Pure Canvas 2D. draw(ctx, time, width, height); time is in SECONDS.
 * One scene / seamless 20-second loop / RGB(0,255,0) key background.
 * Responsive FHD / 2K / 4K. No assets, fonts, DOM, dependencies, or glow.
 * VIDEO EXPORT TARGET: 3840 x 2160, 60 fps, CBR 100,000,000 bit/s.
 * Configure the video encoder separately; this source only draws frames.
 */
function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  const TAU = Math.PI * 2;
  const phase = TAU * (currentScene + sceneProgress);
  const scale = Math.min(width / 1920, height / 1080, minSide / 1080);
  if (!(width > 0 && height > 0) || !Number.isFinite(t)) return;
  const C={key:'#00FF00',ink:'#2D354D',ivory:'#FFF7E8',cream:'#F4DEC0',sand:'#DDBF97',
    red:'#BB455D',redLight:'#DB7183',redDark:'#8E334C',gold:'#E5AF55',goldLight:'#FFD69A',goldDark:'#BC8240',
    blue:'#6D89AC',blueLight:'#9DB4CD',blueDark:'#435779'};
  const clamp=x=>Math.max(0,Math.min(1,x));
  const ease=x=>{x=clamp(x);return x*x*x*(10+x*(-15+6*x));};
  const seg=(a,b)=>ease((loopT-a)/(b-a));
  let carousel=0;
  if(loopT>=3&&loopT<5)carousel=seg(3,5);
  else if(loopT>=5&&loopT<8)carousel=1;
  else if(loopT>=8&&loopT<10)carousel=1+seg(8,10);
  else if(loopT>=10&&loopT<17)carousel=2;
  else if(loopT>=17&&loopT<19.5)carousel=2+seg(17,19.5);
  else if(loopT>=19.5)carousel=3;
  const added=seg(13,13.35)*(1-seg(16.5,17));
  const flight=ease((loopT-11)/2);
  const giftVisible=seg(11,11.16)*(1-seg(16.5,17));
  function gradient(y,h,a,b){const g=ctx.createLinearGradient(0,y,0,y+Math.max(h,1));g.addColorStop(0,a);g.addColorStop(1,b);return g;}
  function paint(f,s,w){if(f){ctx.fillStyle=f;ctx.fill();}if(s){ctx.strokeStyle=s;ctx.lineWidth=w||4;ctx.stroke();}}
  function rp(x,y,w,h,r){r=Math.min(r,w/2,h/2);ctx.beginPath();ctx.moveTo(x+r,y);ctx.lineTo(x+w-r,y);ctx.quadraticCurveTo(x+w,y,x+w,y+r);ctx.lineTo(x+w,y+h-r);ctx.quadraticCurveTo(x+w,y+h,x+w-r,y+h);ctx.lineTo(x+r,y+h);ctx.quadraticCurveTo(x,y+h,x,y+h-r);ctx.lineTo(x,y+r);ctx.quadraticCurveTo(x,y,x+r,y);ctx.closePath();}
  function rr(x,y,w,h,r,f,s,lw){rp(x,y,w,h,r);paint(f,s,lw);}
  function circle(x,y,r,f,s,w){ctx.beginPath();ctx.arc(x,y,r,0,TAU);paint(f,s,w);}
  function line(p,c,w){ctx.beginPath();ctx.moveTo(p[0][0],p[0][1]);for(let i=1;i<p.length;i++)ctx.lineTo(p[i][0],p[i][1]);ctx.strokeStyle=c;ctx.lineWidth=w;ctx.stroke();}
  function poly(p,f,s,w){ctx.beginPath();ctx.moveTo(p[0][0],p[0][1]);for(let i=1;i<p.length;i++)ctx.lineTo(p[i][0],p[i][1]);ctx.closePath();paint(f,s,w);}
  function flake(x,y,r,c,w){ctx.save();ctx.translate(x,y);for(let i=0;i<6;i++){ctx.save();ctx.rotate(i*TAU/6);line([[0,0],[0,-r]],c,w);line([[-r*.23,-r*.64],[0,-r*.43],[r*.23,-r*.64]],c,w);ctx.restore();}ctx.restore();}
  function bow(x,y,color,size){ctx.save();ctx.translate(x,y);ctx.scale(size,size);
    poly([[-4,6],[-16,32],[-21,21],[-30,23],[-17,-1]],color,C.ink,2.8);poly([[4,6],[16,32],[21,21],[30,23],[17,-1]],color,C.ink,2.8);
    ctx.beginPath();ctx.moveTo(-3,1);ctx.bezierCurveTo(-57,-39,-53,26,-3,8);ctx.closePath();paint(color,C.ink,3.2);
    ctx.beginPath();ctx.moveTo(3,1);ctx.bezierCurveTo(57,-39,53,26,3,8);ctx.closePath();paint(color,C.ink,3.2);
    line([[-10,2],[-29,-4]],C.ivory,2.2);line([[10,2],[29,-4]],C.ivory,2.2);rr(-7,-4,14,16,4,C.goldLight,C.ink,2.8);ctx.restore();}

  // Rounded vector lettering has identical metrics without installed fonts.
  const glyphs={
    'A':[[[0,8],[0,2],[2.5,0],[5,2],[5,8]],[[0,4.5],[5,4.5]]],
    'B':[[[0,8],[0,0],[3.5,0],[5,1.4],[5,2.7],[3.5,4],[0,4]],[[3.5,4],[5,5.4],[5,6.6],[3.5,8],[0,8]]],
    'C':[[[5,1],[4,0],[1,0],[0,1],[0,7],[1,8],[4,8],[5,7]]],
    'D':[[[0,8],[0,0],[3,0],[5,2],[5,6],[3,8],[0,8]]],
    'E':[[[5,0],[0,0],[0,8],[5,8]],[[0,4],[4,4]]],
    'F':[[[5,0],[0,0],[0,8]],[[0,4],[4,4]]],
    'G':[[[5,1],[4,0],[1,0],[0,1],[0,7],[1,8],[5,8],[5,4.5],[3,4.5]]],
    'I':[[[0,0],[5,0]],[[2.5,0],[2.5,8]],[[0,8],[5,8]]],
    'L':[[[0,0],[0,8],[5,8]]],
    'O':[[[1,0],[4,0],[5,1],[5,7],[4,8],[1,8],[0,7],[0,1],[1,0]]],
    'R':[[[0,8],[0,0],[3.5,0],[5,1.4],[5,2.7],[3.5,4],[0,4]],[[2.5,4],[5,8]]],
    'S':[[[5,1],[4,0],[1,0],[0,1],[0,3],[1,4],[4,4],[5,5],[5,7],[4,8],[1,8],[0,7]]],
    'T':[[[0,0],[5,0]],[[2.5,0],[2.5,8]]],
    'X':[[[0,0],[5,8]],[[5,0],[0,8]]],
    '0':[[[1,0],[4,0],[5,1],[5,7],[4,8],[1,8],[0,7],[0,1],[1,0]]],
    '1':[[[1,2],[3,0],[3,8]],[[1,8],[5,8]]],
    '2':[[[0,1],[1,0],[4,0],[5,1],[5,3],[0,8],[5,8]]],
    '4':[[[0,0],[0,4.5],[5,4.5]],[[4,0],[4,8]]],
    '8':[[[1,0],[4,0],[5,1],[5,3],[4,4],[1,4],[0,3],[0,1],[1,0]],[[1,4],[0,5],[0,7],[1,8],[4,8],[5,7],[5,5],[4,4]]]
  };
  function lettering(text,x,y,h,c){const s=h/8,w=text.length*5+(text.length-1)*2;ctx.save();ctx.translate(x-w*s/2,y-h/2);ctx.scale(s,s);for(let i=0;i<text.length;i++){const g=glyphs[text[i]]||[];for(const p of g)line(p.map(q=>[q[0]+i*7,q[1]]),c,.72);}ctx.restore();}
  function giftSymbol(){rr(-50,-27,100,84,7,gradient(-27,84,C.redLight,C.redDark),C.ink,4);
    rr(-7,-27,14,84,1,C.goldLight);rr(-50,8,100,12,1,C.goldLight);
    rr(-54,-30,108,15,5,C.redLight,C.ink,3.2);rr(-7,-30,14,15,1,C.goldLight);bow(0,-43,C.blueDark,.69);}
  function bellSymbol(){ctx.beginPath();ctx.moveTo(-42,38);ctx.bezierCurveTo(-31,15,-40,-45,0,-48);ctx.bezierCurveTo(40,-45,31,15,42,38);ctx.closePath();paint(gradient(-48,92,C.goldLight,C.goldDark),C.ink,4);
    rr(-49,34,98,14,6,C.gold,C.ink,3.4);circle(0,53,8,C.goldLight,C.ink,3);circle(0,-55,7,null,C.ink,3);flake(0,0,19,C.ivory,2.8);}
  function ballSymbol(){circle(0,-56,7,null,C.ink,3);rr(-14,-49,28,13,4,C.goldLight,C.ink,2.5);circle(0,7,44,gradient(-37,88,C.blueLight,C.blueDark),C.ink,4);flake(0,7,25,C.ivory,3);}
  function productCard(x,index){
    rr(x-119,328,238,236,16,gradient(328,236,C.ivory,C.cream),C.ink,3.1);
    ctx.save();ctx.translate(x,401);if(index===0)bellSymbol();else if(index===1)ballSymbol();else giftSymbol();ctx.restore();
    lettering(['BELL','BALL','BOX'][index],x,489,16,C.ink);
    circle(x-39,531,9,C.goldLight,C.goldDark,2);line([[x-39,526],[x-39,536]],C.goldDark,1.8);
    lettering(['18','12','24'][index],x+11,531,24,C.ink);
  }

  ctx.save();ctx.setTransform(1,0,0,1,0,0);ctx.globalAlpha=1;ctx.globalCompositeOperation='source-over';ctx.shadowColor='rgba(0,0,0,0)';ctx.shadowBlur=0;ctx.shadowOffsetX=0;ctx.shadowOffsetY=0;if('filter'in ctx)ctx.filter='none';ctx.setLineDash([]);
  ctx.fillStyle=C.key;ctx.fillRect(0,0,width,height);ctx.translate(width/2,height/2);ctx.scale(scale,scale);ctx.translate(-960,-540);ctx.lineCap='round';ctx.lineJoin='round';

  // Three separate supporting objects float gently in their own clear corridors.
  const bagY=659+4*Math.sin(phase*2),bagAngle=.008*Math.sin(phase*2+.7);
  ctx.save();ctx.translate(450,bagY);ctx.rotate(bagAngle);
  ctx.beginPath();ctx.moveTo(-58,-101);ctx.bezierCurveTo(-58,-191,58,-191,58,-101);ctx.strokeStyle=C.ink;ctx.lineWidth=12;ctx.stroke();ctx.strokeStyle=C.goldLight;ctx.lineWidth=6;ctx.stroke();
  rr(-130,-106,260,252,18,gradient(-106,252,C.blueLight,C.blueDark),C.ink,6);
  poly([[112,-106],[130,-88],[130,133],[112,146]],C.blueDark,C.ink,3);
  rr(-130,-106,260,22,8,C.cream,C.ink,4);
  line([[-111,-63],[-111,101]],C.blue,3);
  circle(0,23,44,C.ivory,C.ink,4);circle(0,23,34,null,C.goldDark,2.5);flake(0,23,25,C.redDark,3.4);
  rr(-105,112,210,8,4,C.goldLight);ctx.restore();

  const cardY=365+4*Math.sin(phase*3+.5),cardAngle=.045+.012*Math.sin(phase*2+.4);
  ctx.save();ctx.translate(1450,cardY);ctx.rotate(cardAngle);
  rr(-140,-81,280,162,16,gradient(-81,162,C.blue,C.blueDark),C.ink,5.5);
  rr(-104,-43,43,32,6,C.goldLight,C.ink,2.6);
  line([[-83,-41],[-83,-13]],C.goldDark,2);line([[-101,-27],[-63,-27]],C.goldDark,2);
  for(let i=0;i<3;i++){ctx.beginPath();ctx.arc(79,-24,9+i*9,-.72,.72);ctx.strokeStyle=C.ivory;ctx.lineWidth=2.5;ctx.stroke();}
  for(let group=0;group<4;group++)for(let d=0;d<4;d++)circle(-100+group*49+d*8,31,2.6,C.cream);
  rr(-101,58,83,4,2,C.blueLight);rr(52,58,48,4,2,C.blueLight);ctx.restore();

  const boxX=1458+4*Math.sin(phase*3+1.1),boxY=718+3*Math.sin(phase*2+2.1);
  ctx.save();ctx.translate(boxX,boxY);
  rr(-113,-80,226,174,12,gradient(-80,174,C.redLight,C.redDark),C.ink,5.5);
  rr(-11,-80,22,174,2,C.goldLight);rr(-113,4,226,16,2,C.goldLight);
  rr(-119,-82,238,22,7,C.redLight,C.ink,4);rr(-11,-82,22,22,1,C.goldLight);
  bow(0,-94,C.blueDark,.96);circle(-65,49,20,C.ivory,C.ink,2.8);flake(-65,49,12,C.redDark,2.1);ctx.restore();

  // Fixed phone and screen; all clipping occurs inside opaque phone surfaces.
  rr(745,130,430,780,44,gradient(130,780,C.blue,C.blueDark),C.ink,8);
  rr(759,144,402,752,34,C.cream,C.ink,3.2);
  rr(775,166,370,704,24,C.ivory,C.ink,3);
  rr(907,151,106,9,4.5,C.ink);circle(1026,155,3.8,C.blueDark);
  rr(907,883,106,6,3,C.goldDark);
  ctx.save();rp(778,169,364,698,21);ctx.clip();
  ctx.save();ctx.translate(819,210);ctx.scale(.29,.29);giftSymbol();ctx.restore();
  lettering('GIFTS',960,211,25,C.ink);
  circle(1103,212,18,C.goldLight,C.ink,2.5);
  ctx.save();ctx.translate(1103,212);const pulse=.96+.012*Math.sin(phase*2);ctx.scale(pulse,pulse);ctx.globalAlpha=added;
  line([[-9,0],[-3,6],[9,-7]],C.ink,3.8);ctx.restore();
  rr(793,260,334,42,13,C.cream,C.sand,2);
  circle(815,280,7.5,null,C.blueDark,2.5);line([[820,286],[825,291]],C.blueDark,2.5);
  lettering('GIFTS',960,281,13,C.blueDark);

  rr(792,321,336,253,16,C.cream,C.sand,2.3);
  ctx.save();rp(794,323,332,249,14);ctx.clip();
  // Adjacent copies make index 3 visually identical to index 0 at the loop seam.
  for(let k=-1;k<=4;k++){
    const x=960+(k-carousel)*264;
    if(x+121<794||x-121>1126)continue;
    productCard(x,((k%3)+3)%3);
  }
  ctx.restore();
  for(let i=0;i<3;i++){
    const delta=((carousel-i+4.5)%3)-1.5,w=clamp(1-Math.abs(delta));
    circle(938+i*22,592,3+1.2*w,w>.5?C.goldDark:C.blueLight);
  }
  rr(792,618,220,43,12,C.blueDark,C.ink,2.7);
  line([[815,639],[831,639]],C.ivory,2.6);line([[823,631],[823,647]],C.ivory,2.6);
  lettering('ADD',912,639,18,C.ivory);

  rr(792,697,336,82,16,C.cream,C.sand,2.4);
  lettering('CART',965,737,18,C.ink);
  circle(1091,738,16,C.blueDark,C.ink,2);
  lettering(loopT>=13.1&&loopT<17?'1':'0',1091,738,15,C.ivory);

  // Gift copy travels in a free corridor to the basket, then stays seated.
  if(giftVisible>0){
    const v=1-flight;
    const fx=v*v*v*960+3*v*v*flight*1130+3*v*flight*flight*1200+flight*flight*flight*838;
    const fy=v*v*v*401+3*v*v*flight*600+3*v*flight*flight*719+flight*flight*flight*719;
    ctx.save();ctx.translate(fx,fy);const s=.34-.05*flight;ctx.scale(s,s);ctx.globalAlpha=giftVisible;giftSymbol();ctx.restore();
  }
  // The front lip naturally occludes the lower part of the arriving gift.
  line([[810,716],[821,716],[828,751],[865,751],[873,727]],C.ink,3.5);
  poly([[825,731],[869,731],[864,749],[830,749]],C.blueLight,C.ink,2.5);
  line([[839,734],[839,746]],C.ivory,2);line([[853,734],[853,746]],C.ivory,2);
  circle(833,759,3.5,C.ink);circle(861,759,3.5,C.ink);

  line([[795,807],[1125,807]],C.sand,2);
  poly([[833,834],[847,821],[861,834],[858,834],[858,850],[837,850],[837,834]],null,C.blueDark,2.6);
  ctx.beginPath();ctx.moveTo(960,849);ctx.bezierCurveTo(926,829,949,814,960,830);ctx.bezierCurveTo(971,814,994,829,960,849);ctx.strokeStyle=C.red;ctx.lineWidth=2.7;ctx.stroke();
  rr(1062,830,24,23,4,null,C.blueDark,2.6);ctx.beginPath();ctx.arc(1074,829,6,Math.PI,0);ctx.strokeStyle=C.blueDark;ctx.lineWidth=2.6;ctx.stroke();
  ctx.restore();
  ctx.restore();
}

/*
 * CONCEPT 09 - GINGERBREAD CHRISTMAS BAKERY
 * Pure Canvas 2D. draw(ctx, time, width, height); time is in SECONDS.
 * One scene / seamless 20-second loop / RGB(0,255,0) key background.
 * Responsive FHD / 2K / 4K. No assets, fonts, DOM, dependencies, or glow.
 * VIDEO EXPORT TARGET: 3840 x 2160, 60 fps, CBR 100,000,000 bit/s.
 * Configure the video encoder separately; this source only draws frames.
 */
function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  const TAU = Math.PI * 2;
  const phase = TAU * (currentScene + sceneProgress);
  const scale = Math.min(width / 1920, height / 1080, minSide / 1080);
  if (!(width > 0 && height > 0) || !Number.isFinite(t)) return;
  const C = { key:'#00FF00', ink:'#2D354D', ivory:'#FFF7E8', cream:'#F4DEC0', sand:'#DDBF97',
    red:'#BB455D', redLight:'#DB7183', redDark:'#8E334C', gold:'#E5AF55', goldLight:'#FFD69A', goldDark:'#BC8240',
    blue:'#6D89AC', blueLight:'#9DB4CD', blueDark:'#435779', biscuit:'#CC9459', biscuitLight:'#E9B97E', biscuitDark:'#A8683E' };
  const clamp = x => Math.max(0, Math.min(1, x));
  const ease = x => { x=clamp(x); return x*x*x*(10+x*(-15+6*x)); };
  const seg = (a,b) => ease((loopT-a)/(b-a));
  const lerp = (a,b,u) => a+(b-a)*u;
  const open = seg(0.4,1.8)*(1-seg(18.1,19.0));
  const extension = seg(1.9,4.8)*(1-seg(15.2,18.0));
  const trayX = 306+490*extension;
  const treeFrost = loopT<19.1 ? seg(5.6,7.1) : 0;
  const starFrost = loopT<19.1 ? seg(7.6,9.0) : 0;
  function gradient(y,h,a,b) { const g=ctx.createLinearGradient(0,y,0,y+Math.max(h,1)); g.addColorStop(0,a); g.addColorStop(1,b); return g; }
  function paint(fill,stroke,lw) { if(fill){ctx.fillStyle=fill;ctx.fill();} if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=lw||4;ctx.stroke();} }
  function rp(x,y,w,h,r) { r=Math.min(r,w/2,h/2);ctx.beginPath();ctx.moveTo(x+r,y);ctx.lineTo(x+w-r,y);ctx.quadraticCurveTo(x+w,y,x+w,y+r);ctx.lineTo(x+w,y+h-r);ctx.quadraticCurveTo(x+w,y+h,x+w-r,y+h);ctx.lineTo(x+r,y+h);ctx.quadraticCurveTo(x,y+h,x,y+h-r);ctx.lineTo(x,y+r);ctx.quadraticCurveTo(x,y,x+r,y);ctx.closePath(); }
  function rr(x,y,w,h,r,f,s,lw){rp(x,y,w,h,r);paint(f,s,lw);}
  function circle(x,y,r,f,s,lw){ctx.beginPath();ctx.arc(x,y,r,0,TAU);paint(f,s,lw);}
  function line(p,c,w){ctx.beginPath();ctx.moveTo(p[0][0],p[0][1]);for(let i=1;i<p.length;i++)ctx.lineTo(p[i][0],p[i][1]);ctx.strokeStyle=c;ctx.lineWidth=w;ctx.stroke();}
  function poly(p,f,s,w){ctx.beginPath();ctx.moveTo(p[0][0],p[0][1]);for(let i=1;i<p.length;i++)ctx.lineTo(p[i][0],p[i][1]);ctx.closePath();paint(f,s,w);}
  function star(x,y,r,f,s,w){ctx.beginPath();for(let i=0;i<10;i++){const a=-Math.PI/2+i*Math.PI/5,d=i%2?r*.47:r;const px=x+Math.cos(a)*d,py=y+Math.sin(a)*d;if(!i)ctx.moveTo(px,py);else ctx.lineTo(px,py);}ctx.closePath();paint(f,s,w);}
  function flake(x,y,r,c,w){ctx.save();ctx.translate(x,y);for(let i=0;i<6;i++){ctx.save();ctx.rotate(i*TAU/6);line([[0,0],[0,-r]],c,w);line([[-r*.23,-r*.64],[0,-r*.43],[r*.23,-r*.64]],c,w);ctx.restore();}ctx.restore();}
  function treePoint(u){return {x:906+(6+12*u)*Math.sin(TAU*2*u),y:582+65*u};}
  function starPoint(u){const a=-Math.PI/2+TAU*u;return {x:1081+21*Math.cos(a),y:617+21*Math.sin(a)};}
  function curve(a,b,c,d,u){const v=1-u;return {x:v*v*v*a.x+3*v*v*u*b.x+3*v*u*u*c.x+u*u*u*d.x,y:v*v*v*a.y+3*v*v*u*b.y+3*v*u*u*c.y+u*u*u*d.y};}
  function pipingPose(){
    const dock={x:1285,y:655};
    if(loopT<5)return dock;
    if(loopT<5.6)return curve(dock,{x:1205,y:511},{x:1004,y:512},treePoint(0),seg(5,5.6));
    if(loopT<7.1)return treePoint(treeFrost);
    if(loopT<7.6)return curve(treePoint(1),{x:946,y:557},{x:1027,y:551},starPoint(0),seg(7.1,7.6));
    if(loopT<9)return starPoint(starFrost);
    if(loopT<10)return curve(starPoint(1),{x:1178,y:521},{x:1295,y:526},dock,seg(9,10));
    return dock;
  }
  function jarPose(){
    const dock={x:1518,y:763,a:0};
    if(loopT<9.6||loopT>=15.2)return dock;
    if(loopT<10.5)return {x:1518,y:lerp(763,300,seg(9.6,10.5)),a:0};
    if(loopT<11.3)return {x:lerp(1518,1050,seg(10.5,11.3)),y:300,a:2.65*seg(10.5,11.3)};
    if(loopT<11.6)return {x:1050,y:lerp(300,420,seg(11.3,11.6)),a:2.65};
