  for (let i = 0; i < ledges.length; i++) {
    const a = ledges[i];
    ctx.beginPath();
    ctx.moveTo(a[0], a[2]);
    ctx.quadraticCurveTo(960, a[2] + a[3], a[1], a[2]);
    ctx.lineTo(a[1], a[2] + 12);
    ctx.quadraticCurveTo(960, a[2] + a[3] + 12, a[0], a[2] + 12);
    ctx.closePath();
    paint(C.sand);
  }
  ctx.restore();

  // Fixed topper, with two opaque facets and a short supporting stem.
  rr(955, 222, 10, 39, 5, C.goldDark, C.ink, 3.5);
  star(960, 191, 48, C.gold, C.ink, 6);
  ctx.save();
  starPath(960, 191, 45);
  ctx.clip();
  ctx.beginPath();
  ctx.moveTo(960, 141);
  ctx.lineTo(960, 191);
  ctx.lineTo(912, 217);
  ctx.lineTo(910, 139);
  ctx.closePath();
  paint(C.goldLight);
  ctx.beginPath();
  ctx.moveTo(960, 191);
  ctx.lineTo(1011, 168);
  ctx.lineTo(1011, 244);
  ctx.lineTo(960, 226);
  ctx.closePath();
  paint(C.goldDark);
  ctx.restore();
  circle(960, 191, 4, C.goldLight);

  function ornament(anchorX, anchorY, radius, stem, row, column, style) {
    const amplitude = 0.082 + 0.012 * Math.sin(phase - row * 0.65);
    const angle = amplitude * Math.sin(phase * 4 - row * 0.82 - column * 0.50);
    const cy = stem + 5 + radius;
    const palettes = [
      [C.redLight, C.red, C.redDark],
      [C.goldLight, C.gold, C.goldDark],
      [C.blue, C.blueDark, C.ink]
    ];
    const pal = palettes[(row + column) % 3];
    ctx.save();
    ctx.translate(anchorX, anchorY);
    ctx.rotate(angle);
    line([[0, 0], [0, stem + 2]], C.ink, 2.3);
    rr(-5, stem, 10, 7, 2, C.goldDark, C.ink, 1.8);
    circle(0, cy, radius, gradient(cy - radius, radius * 2, pal[0], pal[2], pal[1]), C.ink, 3.2);
    ctx.save();
    ctx.beginPath();
    ctx.arc(0, cy, radius - 2, 0, TAU);
    ctx.clip();
    if (style % 4 === 0) {
      ctx.beginPath();
      ctx.moveTo(-radius, cy - 3);
      ctx.bezierCurveTo(-radius * 0.4, cy + 5, radius * 0.4, cy + 5, radius, cy - 3);
      ctx.strokeStyle = C.ivory;
      ctx.lineWidth = 3.2;
      ctx.stroke();
      circle(-radius * 0.30, cy - radius * 0.47, 2, C.ivory);
      circle(radius * 0.30, cy - radius * 0.47, 2, C.ivory);
    } else if (style % 4 === 1) {
      snowflake(0, cy, radius * 0.64, C.ivory, 1.7);
    } else if (style % 4 === 2) {
      star(0, cy, radius * 0.64, C.ivory);
      circle(-radius * 0.56, cy - radius * 0.50, 1.7, C.ivory);
    } else {
      for (let j = -1; j <= 1; j++) {
        ctx.beginPath();
        ctx.moveTo(j * radius * 0.52, cy - 6);
        ctx.lineTo(j * radius * 0.52 + 3, cy);
        ctx.lineTo(j * radius * 0.52, cy + 6);
        ctx.lineTo(j * radius * 0.52 - 3, cy);
        ctx.closePath();
        paint(C.ivory);
      }
    }
    ctx.restore();
    ctx.restore();
  }

  const rows = [
    { left: 910, right: 1010, y: 334, sag: 42, beads: 9, radius: 14, stem: 9, hangers: [0.25, 0.75] },
    { left: 850, right: 1070, y: 447, sag: 34, beads: 13, radius: 18, stem: 11, hangers: [1 / 6, 0.5, 5 / 6] },
    { left: 780, right: 1140, y: 565, sag: 42, beads: 17, radius: 18, stem: 9, hangers: [0.125, 0.375, 0.625, 0.875] },
    { left: 725, right: 1195, y: 681, sag: 28, beads: 19, radius: 17, stem: 6, hangers: [1 / 9, 1 / 3, 0.5, 2 / 3, 8 / 9] }
  ];
  for (let rowIndex = 0; rowIndex < rows.length; rowIndex++) {
    const row = rows[rowIndex];
    const sag = row.sag + 1.6 * Math.sin(phase * 2 - rowIndex * 0.70);
    // Both string endpoints are pinned. Only the interior sag changes subtly.
    ctx.beginPath();
    ctx.moveTo(row.left, row.y);
    ctx.quadraticCurveTo(960, row.y + sag, row.right, row.y);
    ctx.strokeStyle = C.ink;
    ctx.lineWidth = 12;
    ctx.stroke();
    ctx.strokeStyle = C.red;
    ctx.lineWidth = 7.5;
    ctx.stroke();
    for (let b = 0; b < row.beads; b++) {
      const u = b / (row.beads - 1);
      const bx = row.left + (row.right - row.left) * u;
      const by = row.y + 2 * u * (1 - u) * sag;
      circle(bx, by, rowIndex === 0 ? 3.4 : 4.1, C.goldLight, C.goldDark, 1.2);
    }
    circle(row.left, row.y, 4.3, C.ink);
    circle(row.right, row.y, 4.3, C.ink);
    for (let c = 0; c < row.hangers.length; c++) {
      const u = row.hangers[c];
      const ax = row.left + (row.right - row.left) * u;
      const ay = row.y + 2 * u * (1 - u) * sag;
      ornament(ax, ay, row.radius, row.stem, rowIndex, c, rowIndex + c);
    }
  }

  function giftBow(x, y, size, index) {
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(size, size);
    // Rigid tail shapes rotate at their attachment points, without stretching.
    for (let side = -1; side <= 1; side += 2) {
      ctx.save();
      ctx.rotate(side * 0.028 * Math.sin(phase * 3 + index * 0.71));
      ctx.beginPath();
      ctx.moveTo(side * 4, -3);
      ctx.lineTo(side * 23, 26);
      ctx.lineTo(side * 15, 22);
      ctx.lineTo(side * 9, 29);
      ctx.lineTo(0, 0);
      ctx.closePath();
      paint(C.gold, C.ink, 3);
      ctx.restore();
    }
    ctx.beginPath();
    ctx.moveTo(-4, -3);
    ctx.bezierCurveTo(-19, -37, -50, -37, -44, -19);
    ctx.bezierCurveTo(-41, -6, -17, 0, -4, -3);
    ctx.closePath();
    paint(C.goldLight, C.ink, 3.5);
    ctx.beginPath();
    ctx.moveTo(4, -3);
    ctx.bezierCurveTo(19, -37, 50, -37, 44, -19);
    ctx.bezierCurveTo(41, -6, 17, 0, 4, -3);
    ctx.closePath();
    paint(C.goldLight, C.ink, 3.5);
    line([[-35, -23], [-17, -11]], C.goldDark, 3);
    line([[35, -23], [17, -11]], C.goldDark, 3);
    rr(-10, -12, 20, 19, 5, C.gold, C.ink, 3.5);
    ctx.restore();
  }

  function gift(gift, index) {
    const x = gift.x;
    const w = gift.w;
    const h = gift.h;
    const bottom = 854;
    const top = bottom - h;
    const ribbon = w * 0.145;
    const lidY = top - 18;

    rr(x - w / 2, top, w, h, 12, gradient(top, h, gift.light, gift.dark, gift.color), C.ink, 6);
    ctx.save();
    rrPath(x - w / 2 + 3, top + 3, w - 6, h - 6, 9);
    ctx.clip();
    rr(x - w / 2 + 3, bottom - 17, w - 6, 18, 2, gift.dark);
    const columns = [-0.32, 0.32];
    for (let column = 0; column < columns.length; column++) {
      for (let k = 0; k < 3; k++) {
        const px = x + w * columns[column];
        const py = top + 28 + k * (h - 54) / 2;
        if (gift.pattern === 0) circle(px, py, 4.5, C.ivory);
        else if (gift.pattern === 1) star(px, py, 6.5, C.ivory);
        else if (gift.pattern === 2) line([[px - 5, py + 5], [px + 5, py - 5]], C.red, 3.5);
        else snowflake(px, py, 7, C.ivory, 1.7);
      }
    }
    line([[x - w / 2 + 13, top + 14], [x - w / 2 + 13, top + h * 0.56]], gift.light, 4);
    ctx.restore();

    rr(x - w / 2 - 7, lidY, w + 14, 28, 8, gift.color, C.ink, 6);
    line([[x - w / 2 + 8, lidY + 7], [x - w / 2 + w * 0.25, lidY + 7]], gift.light, 3.5);
    rr(x - w / 2 + 3, top + h * 0.47, w - 6, 24, 2, C.gold);
    rr(x - w / 2 + 3, top + h * 0.47 + 19, w - 6, 5, 1, C.goldDark);
    rr(x - ribbon / 2, lidY, ribbon, bottom - lidY, 3, C.goldLight);
    rr(x + ribbon / 2 - 5, lidY, 5, bottom - lidY, 1, C.gold);

    // An opaque matte stripe travels inside the ribbon. It never spills onto
    // the key background. At the modulo boundary it is entirely out of view.
    ctx.save();
    rrPath(x - ribbon / 2 + 2, lidY + 2, ribbon - 8, bottom - lidY - 4, 2);
    ctx.clip();
    const travel = fract(currentScene + sceneProgress + index * 0.23);
    const stripeY = lidY - 66 + travel * (bottom - lidY + 132);
    ctx.beginPath();
    ctx.moveTo(x - ribbon, stripeY);
    ctx.lineTo(x + ribbon, stripeY - 13);
    ctx.lineTo(x + ribbon, stripeY + 8);
    ctx.lineTo(x - ribbon, stripeY + 21);
    ctx.closePath();
    paint(C.ivory);
    ctx.restore();
    giftBow(x, lidY - 1, w / 188, index);
  }

  for (let i = 0; i < presents.length; i++) gift(presents[i], i);
  ctx.restore();
}
